func testRefoundGuard(t *testing.T, now *time.Time) RefoundGuard {
	t.Helper()
	dir := filepath.Join(t.TempDir(), "membership")
	return RefoundGuard{PendingPath: filepath.Join(dir, "refound-pending.json"),
		HealthPath: filepath.Join(dir, "cluster-health.json"), Now: func() time.Time { return *now }}
}

func writeHealth(t *testing.T, guard RefoundGuard, status clusterhealth.Status) {
	t.Helper()
	if err := clusterhealth.WriteStatusFile(guard.HealthPath, status); err != nil {
		t.Fatal(err)
	}
}

func (pending RefoundPending) validate() error {
	serverName, err := naming.RegionCell(pending.Cell).ControllerSlot(pending.Slot)
	if err != nil || pending.ServerName != serverName || pending.Attempt < 2 || pending.StartedAt.IsZero() {
		return errors.New("pending refound record lacks an exact regional slot, successor attempt or start time")
	}
	return nil
}

func (guard RefoundGuard) Begin(pending RefoundPending) error {
	if err := pending.validate(); err != nil {
		return err
	}
	wire, err := json.Marshal(pending)
	if err != nil {
		return err
	}
	return writeOwnerOnly(guard.PendingPath, wire)
}

// Clear removes the pending record.
func (guard RefoundGuard) Clear() error {
	if err := os.Remove(guard.PendingPath); err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return err
	}
	return syncDir(filepath.Dir(guard.PendingPath))
}

// WaitCurrent polls the controller's cluster health until the pending
// slot's server is an online, caught-up metadata peer in a view observed
// after the relaunch began, then clears the pending record. On timeout the
// record stays, so no other slot is re-founded meanwhile.
func (guard RefoundGuard) WaitCurrent(ctx context.Context, pending RefoundPending, poll, timeout time.Duration,
	out io.Writer,
) error {
	serverName := pending.ServerName
	deadline := guard.now().Add(timeout)
	last := ""
	for {
		err := guard.current(pending)
		if err == nil {
			return guard.Clear()
		}
		if err.Error() != last {
			last = err.Error()
			fmt.Fprintf(out, "waiting for %s to report current: %v\n", serverName, err)
		}
		if !guard.now().Before(deadline) {
			return fmt.Errorf("%s did not report current within %s (%v); rerun refound for the same slot to keep waiting before re-founding another",
				serverName, timeout, err)
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(poll):
		}
	}
}

// current judges the pending slot from a cluster view that is both fresh and
// observed after the relaunch began: the successor reuses the lost
// instance's server name, so an earlier view says nothing about it.
func (guard RefoundGuard) current(pending RefoundPending) error {
	if err := pending.validate(); err != nil {
		return err
	}
	status, err := clusterhealth.ReadStatusFile(guard.HealthPath)
	if err != nil {
		return fmt.Errorf("read the controller's cluster health %s: %w", guard.HealthPath, err)
	}
	notBefore := guard.now().Add(-RefoundHealthFreshness)
	if pending.StartedAt.After(notBefore) {
		notBefore = pending.StartedAt
	}
	return status.PeerCurrent(pending.ServerName, notBefore)
}

func writeOwnerOnly(path string, data []byte) error {
	dir := filepath.Dir(path)
	if _, err := os.Stat(dir); errors.Is(err, os.ErrNotExist) {
		if err := os.MkdirAll(dir, 0o700); err != nil {
			return err
		}
		if err := syncDir(filepath.Dir(dir)); err != nil {
			return err
		}
	}
	temporary, err := os.CreateTemp(dir, ".refound-*")
	if err != nil {
		return err
	}
	defer os.Remove(temporary.Name())
	if err := temporary.Chmod(0o600); err != nil {
		temporary.Close()
		return err
	}
	if _, err := temporary.Write(data); err != nil {
		temporary.Close()
		return err
	}
	if err := temporary.Sync(); err != nil {
		temporary.Close()
		return err
	}
	if err := temporary.Close(); err != nil {
		return err
	}
	if err := os.Rename(temporary.Name(), path); err != nil {
		return err
	}
	// The record gates the next slot after a crash, so its directory entry
	// must be durable before the caller launches anything.
	return syncDir(dir)
}

func syncDir(dir string) error {
	handle, err := os.Open(dir)
	if err != nil {
		return err
	}
	defer handle.Close()
	return handle.Sync()
}

func WriteStatusFile(path string, status Status) error {
	if path == "" || !filepath.IsAbs(path) {
		return errors.New("cluster health status file path must be absolute")
	}
	wire, err := json.Marshal(status)
	if err != nil {
		return err
	}
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return err
	}
	temporary, err := os.CreateTemp(dir, ".cluster-health-*")
	if err != nil {
		return err
	}
	defer os.Remove(temporary.Name())
	if err := temporary.Chmod(0o600); err != nil {
		temporary.Close()
		return err
	}
	if _, err := temporary.Write(wire); err != nil {
		temporary.Close()
		return err
	}
	if err := temporary.Close(); err != nil {
		return err
	}
	return os.Rename(temporary.Name(), path)
}

// ReadStatusFile reads a status written by WriteStatusFile. The file must be
// a bounded regular file that is not a symbolic link.
func ReadStatusFile(path string) (Status, error) {
	info, err := os.Lstat(path)
	if err != nil {
		return Status{}, err
	}
	if !info.Mode().IsRegular() || info.Size() <= 0 || info.Size() > maxStatusFileBytes {
		return Status{}, errors.New("cluster health status must be a bounded regular file")
	}
	file, err := os.Open(path)
	if err != nil {
		return Status{}, err
	}
	defer file.Close()
	wire, err := io.ReadAll(io.LimitReader(file, maxStatusFileBytes+1))
	if err != nil {
		return Status{}, err
	}
	if len(wire) > maxStatusFileBytes {
		return Status{}, errors.New("cluster health status must be a bounded regular file")
	}
	var status Status
	if err := json.Unmarshal(wire, &status); err != nil {
		return Status{}, fmt.Errorf("decode cluster health status: %w", err)
	}
	return status, nil
}

// PeerCurrent reports whether serverName is an online, caught-up member of a
// metadata group that has a leader, as of a status observed no earlier than
// notBefore.
func (status Status) PeerCurrent(serverName string, notBefore time.Time) error {
	switch {
	case status.ObservedAt.Before(notBefore):
		return fmt.Errorf("cluster health was last observed at %s; is the controller running?",
			status.ObservedAt.Format(time.RFC3339))
	case status.MetaLeader == "":
		return errors.New("the metadata group has no leader")
	case slices.Contains(status.Missing, serverName):
		return fmt.Errorf("%s has not joined the metadata group", serverName)
	case slices.Contains(status.Offline, serverName) || !slices.Contains(status.Online, serverName):
		return fmt.Errorf("%s is offline", serverName)
	case slices.ContainsFunc(status.Lagging, func(peer LaggingPeer) bool { return peer.Name == serverName }):
		return fmt.Errorf("%s is still catching up", serverName)
	case !slices.Contains(status.CaughtUp, serverName):
		// Not lagging is not caught up: a lag within the alert threshold,
		// or a follower's view of another follower, proves nothing.
		return fmt.Errorf("%s has not been reported current with zero lag by the metadata leader in this controller's view",
			serverName)
	}
	return nil
}

func (f *fakeLease) VerifyLeaseHolder(_ context.Context, epoch uint64, candidate, owner string) error {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.checks++
	if epoch == 0 || epoch != f.epoch || candidate != f.candidate || owner != f.owner {
		return authority.ErrFenced
	}
	return nil
}

func (f *fakeLease) set(epoch uint64, candidate, owner string) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.epoch, f.candidate, f.owner = epoch, candidate, owner
}

func newSeedFounderStub() *seedFounderStub {
	return &seedFounderStub{started: make(chan Action, 4), release: make(chan error, 4), canceled: make(chan error, 4)}
}

func (f *seedFounderStub) Replace(ctx context.Context, action Action) error {
	f.mu.Lock()
	f.actions = append(f.actions, action)
	f.mu.Unlock()
	if action.Fence != nil {
		if err := action.Fence(ctx); err != nil {
			return err
		}
	}
	f.started <- action
	select {
	case err := <-f.release:
		return err
	case <-ctx.Done():
		f.canceled <- context.Cause(ctx)
		return ctx.Err()
	}
}

func signedRetirement(t *testing.T, slot string, attempt uint64, instance string) []byte {
	t.Helper()
	_, root, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	now := time.Now().UTC().Truncate(time.Second)
	candidate := bootstrap.RetirementEvidence{SchemaVersion: 1, DeploymentID: "0000000000DMC7WFP9VHV640EP", Cell: "GRU",
		Environment: "production", Role: "controller", Slot: slot, PreviousAttempt: attempt,
		PreviousGeneration: 1, PreviousResultDigest: strings.Repeat("c", 64), PriorInstanceOCID: instance,
		PriorCreateKey: "founder-" + slot + "-key", Disposition: bootstrap.SlotRetirementDisposition,
		ObservedEvidenceDigest: evidenceID, FencingAuthority: "authority-epoch-2", ObservedAt: now}
	envelope, err := bootstrap.SignSlotRetirement(candidate, now, now.Add(time.Hour), root)
	if err != nil {
		t.Fatal(err)
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		t.Fatal(err)
	}
	return wire
}

func seedTopology() Topology {
	return Topology{Cell: "gru", Slots: []string{"controller-a", "controller-b", "controller-c"},
		SeedSlot: "controller-a", SelfSlot: "controller-a"}
}

func quietLogger() *slog.Logger { return slog.New(slog.NewTextHandler(io.Discard, nil)) }

type seedHarness struct {
	lease    *fakeLease
	cell     *fakeCell
	replacer *seedFounderStub
	server   *SeedServer
}

func newSeedHarness(t *testing.T) *seedHarness {
	t.Helper()
	harness := &seedHarness{lease: &fakeLease{}, cell: newFakeCell(), replacer: newSeedFounderStub()}
	harness.lease.set(seedTermEpoch, "000000000057DFR5HRY5QD68EQ", "0000000000P2GFAE1EE5N7T3Q1")
	server, err := NewSeedServer(t.Context(), seedTopology(), SeedServerDependencies{Leases: harness.lease,
		Instances: harness.cell, Replacer: harness.replacer, Logger: quietLogger()})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(server.Close)
	harness.server = server
	return harness
}

func (h *seedHarness) request(t *testing.T, mutate func(*SeedReplaceRequest)) SeedReplaceReply {
	t.Helper()
	request := SeedReplaceRequest{Version: SeedReplaceRequestVersion, Cell: "gru", Slot: "controller-b",
		PreviousAttempt: 1, PriorInstanceOCID: instanceB,
		Retirement: signedRetirement(t, "controller-b", 1, instanceB), Epoch: seedTermEpoch,
		CandidateID: "000000000057DFR5HRY5QD68EQ", OwnerID: "0000000000P2GFAE1EE5N7T3Q1"}
	if mutate != nil {
		mutate(&request)
	}
	payload, err := protocol.EncodeJSON(request)
	if err != nil {
		t.Fatal(err)
	}
	return h.server.Handle(t.Context(), payload)
}

func awaitStarted(t *testing.T, replacer *seedFounderStub) Action {
	t.Helper()
	select {
	case action := <-replacer.started:
		return action
	case <-time.After(5 * time.Second):
		t.Fatal("routed replacement never started")
	}
	return Action{}
}

func waitFor(t *testing.T, condition func() bool) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for !condition() {
		if time.Now().After(deadline) {
			t.Fatal("condition not reached")
		}
		time.Sleep(5 * time.Millisecond)
	}
}

func (request SeedReplaceRequest) validate(topology Topology) error {
	if request.Version != SeedReplaceRequestVersion || request.Cell != topology.Cell {
		return errors.New("request is for another schema or cell")
	}
	if !slices.Contains(topology.Slots, request.Slot) || request.Slot == topology.SeedSlot ||
		request.Slot == topology.SelfSlot {
		return errors.New("request names no replaceable non-seed peer slot")
	}
	if request.PreviousAttempt == 0 || request.PriorInstanceOCID == "" || len(request.Retirement) == 0 ||
		len(request.Retirement) > maxEvidenceBytes {
		return errors.New("request lacks the exact prior attempt or a bounded retirement envelope")
	}
	if request.Epoch == 0 || request.CandidateID == "" || request.OwnerID == "" ||
		len(request.CandidateID) > 128 || len(request.OwnerID) > 128 {
		return errors.New("request lacks the leader's authority term")
	}
	// The envelope is decoded only to route it, exactly like evidence on
	// disk; the founder verifies its root signature against the ledger.
	retirement, err := bootstrap.DecodeSlotRetirementCandidate(request.Retirement)
	if err != nil || retirement.Slot != request.Slot || retirement.PreviousAttempt != request.PreviousAttempt ||
		retirement.PriorInstanceOCID != request.PriorInstanceOCID {
		return errors.New("retirement envelope does not name the requested slot attempt and instance")
	}
	return nil
}

func (replacer SeedRoutedReplacer) Replace(ctx context.Context, action Action) error {
	if replacer.Request == nil || replacer.Leadership == nil {
		return ErrReplacerUnavailable
	}
	snapshot := replacer.Leadership.Current()
	if !snapshot.CanMutate() || action.Epoch == 0 || snapshot.Epoch != action.Epoch {
		return errors.New("controller authority term ended before routing the replacement to the seed")
	}
	// Renew the lease first, so the seed's read-only check sees a fresh
	// record for this exact term.
	if action.Fence != nil {
		if err := action.Fence(ctx); err != nil {
			return fmt.Errorf("authority fence: %w", err)
		}
	}
	payload, err := protocol.EncodeJSON(SeedReplaceRequest{Version: SeedReplaceRequestVersion, Cell: replacer.Cell,
		Slot: action.Slot, PreviousAttempt: action.PreviousAttempt, PriorInstanceOCID: action.PriorInstanceOCID,
		Retirement: action.Retirement.Wire, Epoch: action.Epoch, CandidateID: snapshot.CandidateID,
		OwnerID: snapshot.OwnerID})
	if err != nil {
		return err
	}
	requestCtx, cancel := context.WithTimeout(ctx, seedRequestTimeout)
	defer cancel()
	wire, err := replacer.Request(requestCtx, payload)
	if err != nil {
		return fmt.Errorf("route replacement to the seed controller: %w", err)
	}
	var reply SeedReplaceReply
	if err := protocol.DecodeStrict(wire, &reply, 4<<10); err != nil {
		return fmt.Errorf("decode seed replacement reply: %w", err)
	}
	switch reply.Status {
	case SeedAccepted, SeedInProgress, SeedDone:
		return nil
	case SeedFailed:
		return fmt.Errorf("seed replacement failed: %s", reply.Error)
	case SeedRefused:
		return fmt.Errorf("%w: %s", ErrSeedRefused, reply.Error)
	}
	return fmt.Errorf("seed replacement reply has unknown status %q", reply.Status)
}

func NewSeedServer(ctx context.Context, topology Topology, deps SeedServerDependencies) (*SeedServer, error) {
	if err := topology.Validate(); err != nil {
		return nil, err
	}
	if topology.SelfSlot != topology.SeedSlot {
		return nil, errors.New("only the seed controller serves slot replacement requests")
	}
	if deps.Leases == nil || deps.Instances == nil || deps.Replacer == nil {
		return nil, errors.New("seed replacement server dependencies are incomplete")
	}
	if deps.Logger == nil {
		deps.Logger = slog.Default()
	}
	base, stop := context.WithCancel(context.WithoutCancel(ctx))
	server := &SeedServer{topology: topology, deps: deps, base: base, stop: stop}
	context.AfterFunc(ctx, stop)
	return server, nil
}

// Close cancels any running replacement and waits for it, so no founder OCI
// call outlives the controller.
func (s *SeedServer) Close() {
	// Stopping under the lock orders every job start before the wait.
	s.mu.Lock()
	s.stop()
	s.mu.Unlock()
	s.jobs.Wait()
}

// Handle answers one encoded request. It never blocks on the replacement
// itself: an accepted request runs in the background and later requests for
// the same retirement report its progress.
func (s *SeedServer) Handle(ctx context.Context, payload []byte) SeedReplaceReply {
	refuse := func(err error) SeedReplaceReply {
		s.deps.Logger.Warn("seed refused a controller slot replacement request", "error", err)
		return SeedReplaceReply{Status: SeedRefused, Error: err.Error()}
	}
	if s.base.Err() != nil {
		return refuse(errors.New("seed controller is stopping"))
	}
	var request SeedReplaceRequest
	if len(payload) == 0 || len(payload) > maxSeedRequestBytes {
		return refuse(errors.New("request size is out of bounds"))
	}
	if err := protocol.DecodeStrict(payload, &request, maxSeedRequestBytes); err != nil {
		return refuse(errors.New("request is not a strict replacement request"))
	}
	if err := request.validate(s.topology); err != nil {
		return refuse(err)
	}
	if err := s.deps.Leases.VerifyLeaseHolder(ctx, request.Epoch, request.CandidateID, request.OwnerID); err != nil {
		return refuse(fmt.Errorf("requesting controller does not hold authority epoch %d: %w", request.Epoch, err))
	}
	key := request.key()
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.base.Err() != nil {
		return refuse(errors.New("seed controller is stopping"))
	}
	if job := s.job; job != nil {
		switch {
		case job.key == key && job.running:
			return SeedReplaceReply{Status: SeedInProgress}
		case job.key == key && job.err != nil && !job.request.sameTerm(request):
			// The term that started the failed attempt ended (its fence
			// most likely cancelled it); the new term resumes at once.
		case job.key == key && job.err != nil:
			// Report the failure once; the leader's retry backoff decides
			// when the next request starts a fresh attempt.
			s.job = nil
			return SeedReplaceReply{Status: SeedFailed, Error: job.err.Error()}
		case job.key == key:
			return SeedReplaceReply{Status: SeedDone}
		case job.running:
			return refuse(fmt.Errorf("seed is already replacing slot %s", job.request.Slot))
		}
	}
	job := &seedJob{key: key, request: request, running: true}
	s.job = job
	s.jobs.Add(1)
	go s.run(job)
	s.deps.Logger.Info("seed accepted a routed controller slot replacement", "slot", request.Slot,
		"previous_attempt", request.PreviousAttempt, "prior_instance", request.PriorInstanceOCID,
		"epoch", request.Epoch, "leader", request.CandidateID)
	return SeedReplaceReply{Status: SeedAccepted}
}

func (s *SeedServer) run(job *seedJob) {
	defer s.jobs.Done()
	request := job.request
	fence := func(ctx context.Context) error {
		return s.deps.Leases.VerifyLeaseHolder(ctx, request.Epoch, request.CandidateID, request.OwnerID)
	}
	poll := seedFencePoll
	ctx, cancel := context.WithCancelCause(s.base)
	defer cancel(context.Canceled)
	go func() {
		ticker := time.NewTicker(poll)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				if err := fence(ctx); err != nil && ctx.Err() == nil {
					cancel(fmt.Errorf("requesting authority term ended during slot replacement: %w", err))
					return
				}
			}
		}
	}()
	err := s.execute(ctx, request, fence)
	if err == nil && ctx.Err() != nil {
		err = context.Cause(ctx)
	}
	s.mu.Lock()
	job.running, job.err = false, err
	s.mu.Unlock()
	s.record(request, err)
	if err != nil {
		s.deps.Logger.Warn("routed controller slot replacement failed", "slot", request.Slot,
			"previous_attempt", request.PreviousAttempt, "epoch", request.Epoch, "error", err)
		return
	}
	s.deps.Logger.Info("routed controller slot replacement finished", "slot", request.Slot,
		"attempt", request.PreviousAttempt+1, "epoch", request.Epoch)
}

func (s *SeedServer) execute(ctx context.Context, request SeedReplaceRequest, fence func(context.Context) error) error {
	// Independent of the leader's observation: an instance that may still
	// run is never replaced by a routed request.
	lifecycle, err := s.deps.Instances.Lifecycle(ctx, request.PriorInstanceOCID)
	if err != nil {
		return fmt.Errorf("observe prior instance %s: %w", request.PriorInstanceOCID, err)
	}
	if lifecycle != LifecycleTerminated {
		return fmt.Errorf("prior instance %s is %s, not %s", request.PriorInstanceOCID, lifecycle, LifecycleTerminated)
	}
	if err := fence(ctx); err != nil {
		return fmt.Errorf("authority fence: %w", err)
	}
	sum := sha256.Sum256(request.Retirement)
	return s.deps.Replacer.Replace(ctx, Action{Slot: request.Slot, PreviousAttempt: request.PreviousAttempt,
		PriorInstanceOCID: request.PriorInstanceOCID, Epoch: request.Epoch,
		Retirement: Evidence{Slot: request.Slot, PreviousAttempt: request.PreviousAttempt,
			PriorInstanceOCID: request.PriorInstanceOCID, Digest: hex.EncodeToString(sum[:]), Wire: request.Retirement},
		Reason: "routed by authority leader " + request.CandidateID, Fence: fence})
}

