func New(topology Topology, deps Dependencies) (*Reconciler, error) {
	if err := topology.Validate(); err != nil {
		return nil, err
	}
	if deps.Leadership == nil || deps.Peers == nil || deps.Ledger == nil || deps.Instances == nil ||
		deps.Evidence == nil {
		return nil, errors.New("membership reconciler dependencies are incomplete")
	}
	if deps.Now == nil {
		deps.Now = time.Now
	}
	if deps.Logger == nil {
		deps.Logger = slog.Default()
	}
	return &Reconciler{topology: topology, deps: deps,
		state: State{Slots: make(map[string]SlotStatus)}, requested: make(map[string]retirementRequestMark)}, nil
}

// Run evaluates membership until ctx ends. Errors in one pass are logged and
// retried on the next tick; they never stop the controller.
func (r *Reconciler) Run(ctx context.Context) error {
	ticker := time.NewTicker(DefaultInterval)
	defer ticker.Stop()
	for {
		if err := r.Tick(ctx); err != nil && ctx.Err() == nil {
			r.deps.Logger.Warn("controller membership pass failed", "error", err)
		}
		select {
		case <-ctx.Done():
			return nil
		case <-ticker.C:
		}
	}
}

// Statuses returns the last evaluated slot statuses, sorted by slot.
func (r *Reconciler) Statuses() []SlotStatus {
	r.mu.Lock()
	defer r.mu.Unlock()
	return slices.Clone(r.statuses)
}

// Tick is one complete observe, decide and act pass.
func (r *Reconciler) Tick(ctx context.Context) error {
	snapshot := r.deps.Leadership.Current()
	if !snapshot.CanMutate() {
		r.reset(0)
		return nil
	}
	r.mu.Lock()
	if r.epoch != snapshot.Epoch {
		// A new term starts every grace period from its own observations.
		r.state, r.epoch = State{Slots: make(map[string]SlotStatus)}, snapshot.Epoch
		r.requested = make(map[string]retirementRequestMark)
	}
	previous := r.state.clone()
	r.mu.Unlock()
	observation, err := r.observe(ctx)
	if err != nil {
		return err
	}
	next, actions := Decide(r.topology, previous, observation)
	for _, action := range actions {
		next.Slots[action.Slot] = r.execute(ctx, snapshot.Epoch, action, next.Slots[action.Slot], observation.At)
	}
	r.requestRetirements(ctx, snapshot.Epoch, next, observation)
	r.commit(snapshot.Epoch, previous, next)
	return nil
}

func (r *Reconciler) observe(ctx context.Context) (Observation, error) {
	meta, err := r.deps.Peers.Meta(ctx)
	if err != nil {
		return Observation{}, fmt.Errorf("read JetStream metadata peers: %w", err)
	}
	ledger, err := r.deps.Ledger.Slots(ctx, r.topology.Slots)
	if err != nil {
		return Observation{}, fmt.Errorf("read controller slot ledger: %w", err)
	}
	lifecycle := make(map[string]string, len(ledger))
	for _, slot := range r.topology.Slots {
		pinned := ledger[slot]
		if slot == r.topology.SelfSlot || pinned.InstanceOCID == "" {
			continue
		}
		state, err := r.deps.Instances.Lifecycle(ctx, pinned.InstanceOCID)
		if err != nil {
			if ctx.Err() != nil {
				return Observation{}, ctx.Err()
			}
			// An unobservable instance is held, never assumed terminated.
			r.deps.Logger.Debug("controller slot instance unobservable", "slot", slot, "error", err)
			continue
		}
		lifecycle[slot] = state
	}
	evidence, err := r.deps.Evidence.Evidence(ctx)
	if err != nil {
		return Observation{}, fmt.Errorf("read retirement evidence: %w", err)
	}
	return Observation{At: r.deps.Now().UTC(), Meta: meta, Ledger: ledger, Lifecycle: lifecycle,
		Evidence: evidence}, nil
}

func (r *Reconciler) execute(ctx context.Context, epoch uint64, action Action, status SlotStatus,
	at time.Time,
) SlotStatus {
	fail := func(err error) SlotStatus {
		status.LastFailure, status.LastError = at, err.Error()
		r.deps.Logger.Warn("controller slot replacement failed", "slot", action.Slot,
			"previous_attempt", action.PreviousAttempt, "error", err)
		return status
	}
	unavailable := func() SlotStatus {
		// Report the decision, but do not hold the single replacement slot.
		status = fail(ErrReplacerUnavailable)
		status.Phase, status.Reason, status.PendingAttempt = PhaseHeld, ErrReplacerUnavailable.Error(), 0
		return status
	}
	if r.deps.Replacer == nil {
		return unavailable()
	}
	if err := r.deps.Leadership.Guard(ctx, epoch); err != nil {
		return fail(fmt.Errorf("authority fence: %w", err))
	}
	r.deps.Logger.Info("replacing controller slot", "slot", action.Slot, "previous_attempt", action.PreviousAttempt,
		"prior_instance", action.PriorInstanceOCID, "reason", action.Reason, "epoch", epoch)
	// The term's fence extends through the whole replacement: the context
	// ends as soon as this controller stops holding the epoch, and the
	// replacer rechecks the guard right before each mutation.
	fencedCtx, stopFence := r.termContext(ctx, epoch)
	defer stopFence()
	action.Epoch = epoch
	action.Fence = func(fenceCtx context.Context) error { return r.deps.Leadership.Guard(fenceCtx, epoch) }
	if err := r.deps.Replacer.Replace(fencedCtx, action); err != nil {
		if errors.Is(err, ErrReplacerUnavailable) {
			return unavailable()
		}
		return fail(err)
	}
	status.LastFailure, status.LastError = timeZero, ""
	r.recordReplacement(ctx, epoch, action)
	return status
}

// termFencePoll is how often a running replacement rechecks that this
// controller still holds the term that decided it.
var termFencePoll = time.Second

// termContext ends when ctx ends or when this controller no longer holds
// epoch with mutation rights.
func (r *Reconciler) termContext(ctx context.Context, epoch uint64) (context.Context, context.CancelFunc) {
	termCtx, cancel := context.WithCancelCause(ctx)
	go func() {
		ticker := time.NewTicker(termFencePoll)
		defer ticker.Stop()
		for {
			select {
			case <-termCtx.Done():
				return
			case <-ticker.C:
				if snapshot := r.deps.Leadership.Current(); !snapshot.CanMutate() || snapshot.Epoch != epoch {
					cancel(errors.New("controller authority term ended during slot replacement"))
					return
				}
			}
		}
	}()
	return termCtx, func() { cancel(context.Canceled) }
}

func Decide(topology Topology, previous State, observation Observation) (State, []Action) {
	next := previous.clone()
	slots := slices.Clone(topology.Slots)
	slices.Sort(slots)
	online := make(map[string]bool, len(slots))
	for _, peer := range observation.Meta.Peers {
		online[peer.Name] = peer.Online
	}
	onlineSlots := 0
	for _, slot := range slots {
		if slot == topology.SelfSlot || online[topology.ServerName(slot)] {
			onlineSlots++
		}
	}
	quorum := observation.Meta.Leader != "" && onlineSlots >= topology.quorum()
	replacing := false
	for _, slot := range slots {
		status, ok := next.Slots[slot]
		if (!ok || status.Phase != PhaseReplacing) && slot != topology.SelfSlot && slot != topology.SeedSlot {
			if pending, inFlight := inFlightSuccessor(slot, observation); inFlight {
				// A new term, or a restarted leader, has no memory of a
				// replacement an earlier term admitted. The ledger does: its
				// incomplete successor HEAD is bound to this exact evidence, so
				// resume it instead of holding the slot as ledger-incomplete
				// and letting another slot start a concurrent replacement.
				status.Slot, status.Phase, status.PendingAttempt = slot, PhaseReplacing, pending
				next.Slots[slot] = status
				ok = true
			}
		}
		if ok && status.Phase == PhaseReplacing && abandonedBeforeAdmission(slot, status, observation) {
			// The successor was never admitted (the ledger still holds the
			// completed prior attempt) and the evidence that would let it be
			// admitted is gone. Nothing was launched, so release the gate and
			// hold the slot for fresh evidence instead of blocking every
			// other replacement for the rest of the term.
			status.Phase, status.PendingAttempt, status.LastFailure, status.LastError = PhaseHeld, 0, timeZero, ""
			next.Slots[slot] = status
		}
		if ok && status.Phase == PhaseReplacing || admittedSuccessor(observation.Ledger[slot]) {
			// The verified ledger HEAD reserves the single replacement slot
			// even when the evidence needed to resume it is not on hand:
			// the founder persists the successor HEAD before any OCI launch.
			replacing = true
		}
	}
	var actions []Action
	for _, slot := range slots {
		status := next.Slots[slot]
		status.Slot = slot
		ledger := observation.Ledger[slot]
		lifecycle := observation.Lifecycle[slot]
		status.Attempt, status.InstanceOCID, status.Lifecycle = ledger.Attempt, ledger.InstanceOCID, lifecycle
		status.Online = slot == topology.SelfSlot || online[topology.ServerName(slot)]
		evidence, hasEvidence := observation.Evidence[slot]
		if status.Phase == PhaseReplacing {
			status, actions = decideReplacing(status, ledger, evidence, hasEvidence, quorum, observation, actions)
			next.Slots[slot] = status
			continue
		}
		switch {
		case slot == topology.SelfSlot:
			status = healthy(status, ReasonLocal)
			next.Slots[slot] = status
			continue
		case status.Online && lifecycle == LifecycleTerminated && ledger.Complete:
			status.Phase, status.Reason = PhaseHeld, ReasonTerminatedButOnline
			next.Slots[slot] = status
			continue
		case status.Online:
			next.Slots[slot] = healthy(status, ReasonOnline)
			continue
		}
		if status.OfflineSince.IsZero() {
			status.OfflineSince = observation.At
		}
		terminated := lifecycle == LifecycleTerminated
		if !terminated && observation.At.Sub(status.OfflineSince) < DefaultOfflineGrace {
			status.Phase, status.Reason = PhaseSuspect, ReasonOfflineWithinGrace
			next.Slots[slot] = status
			continue
		}
		status.Phase = PhaseHeld
		switch {
		case slot == topology.SeedSlot:
			status.Reason = ReasonSeedSlot
		case ledger.Complete && ledger.Attempt == 0 && ledger.InstanceOCID != "":
			status.Reason = "accepted controller has no current replacement launch authority"
		case !ledger.Complete || ledger.Attempt == 0 || ledger.InstanceOCID == "":
			status.Reason = ReasonLedgerIncomplete
		case lifecycle == "":
			status.Reason = ReasonInstanceUnobserved
		case !terminated:
			status.Reason = fmt.Sprintf("%s (%s is %s)", ReasonInstanceAlive, ledger.InstanceOCID, lifecycle)
		case !quorum:
			status.Reason = ReasonQuorumLost
		case replacing:
			status.Reason = ReasonOtherReplacement
		case !hasEvidence || evidence.Slot != slot || evidence.PreviousAttempt != ledger.Attempt ||
			evidence.PriorInstanceOCID != ledger.InstanceOCID || len(evidence.Wire) == 0:
			status.Reason = fmt.Sprintf("%s for %s attempt %d instance %s", ReasonAwaitingEvidence, slot,
				ledger.Attempt, ledger.InstanceOCID)
		case !status.LastFailure.IsZero() && observation.At.Sub(status.LastFailure) < DefaultRetryBackoff:
			status.Reason = ReasonRetryBackoff
		default:
			status.Phase, status.Reason = PhaseReplacing, ReasonReplacing
			status.PendingAttempt = ledger.Attempt + 1
			replacing = true
			actions = append(actions, Action{Slot: slot, PreviousAttempt: ledger.Attempt,
				PriorInstanceOCID: ledger.InstanceOCID, Retirement: evidence,
				Reason: "pinned instance " + ledger.InstanceOCID + " is terminated"})
		}
		next.Slots[slot] = status
	}
	return next, actions
}

// decideReplacing follows one in-flight replacement until the successor
// attempt completes. It re-emits the same action, bound to the same evidence,
// until the ledger reports completion, so a crashed or failed actuator call is
// resumed rather than restarted with a new attempt.
func decideReplacing(status SlotStatus, ledger LedgerSlot, evidence Evidence, hasEvidence bool,
	quorum bool, observation Observation, actions []Action,
) (SlotStatus, []Action) {
	previous := status.PendingAttempt - 1
	if ledger.Attempt >= status.PendingAttempt && ledger.Complete {
		status.PendingAttempt, status.LastFailure, status.LastError = 0, timeZero, ""
		if status.Online {
			return healthy(status, ReasonOnline), actions
		}
		// The successor gets a fresh grace to start and catch up.
		status.Phase, status.Reason, status.OfflineSince = PhaseSuspect, ReasonRejoining, observation.At
		return status, actions
	}
	switch {
	case !quorum:
		status.Reason = ReasonQuorumLost
	case !hasEvidence || evidence.Slot != status.Slot || evidence.PreviousAttempt != previous ||
		ledger.Attempt != previous && ledger.Attempt != status.PendingAttempt || len(evidence.Wire) == 0:
		status.Reason = fmt.Sprintf("%s for %s attempt %d", ReasonAwaitingEvidence, status.Slot, previous)
	case !status.LastFailure.IsZero() && observation.At.Sub(status.LastFailure) < DefaultRetryBackoff:
		status.Reason = ReasonRetryBackoff
	default:
		status.Reason = ReasonReplacing
		actions = append(actions, Action{Slot: status.Slot, PreviousAttempt: previous,
			PriorInstanceOCID: evidence.PriorInstanceOCID, Retirement: evidence, Reason: "resume replacement"})
	}
	return status, actions
}

// inFlightSuccessor reports an admitted but incomplete successor attempt whose
// HEAD was advanced with the retirement evidence currently on hand.
func inFlightSuccessor(slot string, observation Observation) (uint64, bool) {
	ledger := observation.Ledger[slot]
	evidence, ok := observation.Evidence[slot]
	if !ok || ledger.Complete || ledger.Attempt < 2 || ledger.Retirement == "" ||
		evidence.Slot != slot || evidence.Digest != ledger.Retirement ||
		evidence.PreviousAttempt+1 != ledger.Attempt || len(evidence.Wire) == 0 {
		return 0, false
	}
	return ledger.Attempt, true
}

// admittedSuccessor reports a ledger HEAD that already admitted an incomplete
// successor attempt through a retirement, whether or not this term holds the
// evidence that admitted it.
func admittedSuccessor(ledger LedgerSlot) bool {
	return !ledger.Complete && ledger.Attempt >= 2 && ledger.Retirement != ""
}

// abandonedBeforeAdmission reports a remembered replacement whose successor
// the ledger never admitted and whose evidence is no longer usable to admit
// it: the ledger still records the completed prior attempt.
func abandonedBeforeAdmission(slot string, status SlotStatus, observation Observation) bool {
	previous := status.PendingAttempt - 1
	ledger := observation.Ledger[slot]
	if status.PendingAttempt == 0 || !ledger.Complete || ledger.Attempt != previous {
		return false
	}
	evidence, ok := observation.Evidence[slot]
	return !ok || evidence.Slot != slot || evidence.PreviousAttempt != previous || len(evidence.Wire) == 0
}

func healthy(status SlotStatus, reason string) SlotStatus {
	status.Phase, status.Reason = PhaseHealthy, reason
	status.OfflineSince, status.PendingAttempt, status.LastFailure, status.LastError = timeZero, 0, timeZero, ""
	return status
}

func (s Snapshot) CanMutate() bool {
	return entityid.Valid(s.DeploymentID) && s.Ready && s.Leader && s.Epoch > 0 && s.Revision > 0 &&
		!s.ExpiresAt.IsZero() && time.Now().Before(s.ExpiresAt)
}

func init() {
	if directory := os.Getenv("TS_MEMBER_PROTOCOL_FIXTURE"); directory != "" {
		if err := serveMemberFixture(directory); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		os.Exit(0)
	}
}

type fixtureConfig struct {
	StatusMutation  string `json:"status_mutation"`
	ProofMutation   string `json:"proof_mutation"`
	ReceiptMutation string `json:"receipt_mutation"`
	LostPOST        bool   `json:"lost_post"`
	HideOperation   bool   `json:"hide_operation"`
	RestartNonce    bool   `json:"restart_nonce"`
}

func fixtureIdentity(pid int) Identity {
	return Identity{Process: Process{PID: pid, StartNonce: strings.Repeat("1", 32)},
		Scope:     Scope{ClusterID: strings.Repeat("b", 32), TenantID: "01HW000000E008000000000001", DatabaseID: "01HW000000E008000000000002", ShardID: 1, MemberID: "01HW000000E008000000000003", Incarnation: strings.Repeat("c", 32)},
		Authority: Authority{Epoch: 7, ConfigurationID: strings.Repeat("d", 64), CertificateSHA256: strings.Repeat("e", 64), TLSLeafSHA256: strings.Repeat("f", 64)}}
}

func fixtureSurvivor() Survivor {
	return Survivor{MemberID: "01HW000000E008000000000004", Incarnation: strings.Repeat("3", 32)}
}

func serveMemberFixture(directory string) error {
	listener, err := net.Listen("unix", filepath.Join(directory, "control", "member.sock"))
	if err != nil {
		return err
	}
	if err := os.Chmod(listener.Addr().String(), 0o602); err != nil {
		return err
	}
	return http.Serve(listener, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		configBytes, err := os.ReadFile(filepath.Join(directory, "config.json"))
		if err != nil {
			panic(err)
		}
		var config fixtureConfig
		if err := json.Unmarshal(configBytes, &config); err != nil {
			panic(err)
		}
		identity := fixtureIdentity(os.Getpid())
		if config.RestartNonce {
			identity.Process.StartNonce = strings.Repeat("9", 32)
		}
		challenge := r.URL.Query().Get("nonce")
		status := Status{SchemaVersion: 2, Nonce: challenge, Process: identity.Process, Scope: identity.Scope, Authority: identity.Authority, Local: Local{true, true, true, true}, Serving: true, Capabilities: Capabilities{true, true}}
		survivor := fixtureSurvivor()
		code := http.StatusOK
		var reply any
		switch r.URL.Path {
		case "/v1/member/status":
			reply = status
		case "/v1/member/serving-proof":
			reply = ServingProof{SchemaVersion: 1, Nonce: challenge, Process: identity.Process, Scope: identity.Scope, Authority: identity.Authority, Serving: true, Listeners: Listeners{true, true},
				Object:      ObjectProof{RootSHA256: strings.Repeat("5", 64), TargetSHA256: strings.Repeat("6", 64), NativeCommitSeqAtRecovery: 30, InboxArchiveSHA256AtRecovery: strings.Repeat("8", 64), LocalSourceSequence: 12, RemoteInboxDurableSequence: 9, RemoteAppliedSequence: 9},
				Replication: ReplicationProof{LocalSourceSequence: 12, PeerMemberID: survivor.MemberID, PeerIncarnation: survivor.Incarnation, CurrentAuthenticated: true, PeerDurableSequence: 12, PeerAppliedSequence: 12, LocalInboxDurableSequence: 9, LocalInboxAppliedSequence: 9}}
		case "/v1/member/drain", "/v1/member/drain-status":
			requestPath := filepath.Join(directory, "request.json")
			var request DrainRequest
			if r.Method == http.MethodPost {
				body, err := io.ReadAll(r.Body)
				if err != nil {
					panic(err)
				}
				if err := json.Unmarshal(body, &request); err != nil {
					panic(err)
				}
				log, err := os.OpenFile(filepath.Join(directory, "posts"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
				if err != nil {
					panic(err)
				}
				_, err = log.Write(append(body, '\n'))
				if err != nil {
					panic(err)
				}
				if err := log.Sync(); err != nil {
					panic(err)
				}
				if err := log.Close(); err != nil {
					panic(err)
				}
				if err := os.WriteFile(requestPath, body, 0o600); err != nil {
					panic(err)
				}
				if config.LostPOST {
					connection, _, err := w.(http.Hijacker).Hijack()
					if err != nil {
						panic(err)
					}
					connection.Close()
					return
				}
				challenge = request.Nonce
			} else {
				body, err := os.ReadFile(requestPath)
				if errors.Is(err, os.ErrNotExist) || config.HideOperation {
					code = http.StatusNotFound
					reply = struct{}{}
					break
				}
				if err != nil {
					panic(err)
				}
				if err := json.Unmarshal(body, &request); err != nil {
					panic(err)
				}
			}
			if config.ReceiptMutation == "pending" {
				code = http.StatusAccepted
				reply = DrainEnvelope{SchemaVersion: 1, Nonce: challenge, Process: identity.Process, OperationID: request.OperationID, State: "pending"}
				break
			}
			receipt := DrainReceipt{SchemaVersion: 1, OperationID: request.OperationID, RequestNonce: request.Nonce, RequestedProcess: request.Expected.Process, DrainedProcess: identity.Process, Scope: request.Expected.Scope, Authority: request.Expected.Authority,
				LocalSourceOrigin: Origin{request.Expected.Scope.MemberID, request.Expected.Scope.Incarnation}, LocalSourceDurableSequence: 15, ArchivedSourceSequence: 15, ObjectRootSHA256: strings.Repeat("5", 64),
				Peer: DrainPeer{Origin: Origin{survivor.MemberID, survivor.Incarnation}, DurableSequence: 15, AppliedSequence: 15, LocalInboxDurableSequence: 9, LocalInboxAppliedSequence: 9}, ReplicationQuiesced: true}
			switch config.ReceiptMutation {
			case "lag":
				receipt.Peer.AppliedSequence = 14
			case "root":
				receipt.ObjectRootSHA256 = ""
			case "nonce":
				receipt.RequestNonce = strings.Repeat("a", 32)
			case "survivor":
				receipt.Peer.Origin.MemberID = request.Expected.Scope.MemberID
			}
			digest, err := receipt.digest()
			if err != nil {
				panic(err)
			}
			if config.ReceiptMutation == "digest" {
				digest = strings.Repeat("0", 64)
			}
			reply = DrainEnvelope{SchemaVersion: 1, Nonce: challenge, Process: identity.Process, OperationID: request.OperationID, State: "complete", ReceiptSHA256: &digest, Receipt: &receipt}
		default:
			code = http.StatusNotFound
			reply = struct{}{}
		}
		body, err := json.Marshal(reply)
		if err != nil {
			panic(err)
		}
		if r.URL.Path == "/v1/member/status" {
			body = mutateStatus(body, config.StatusMutation)
		}
		if r.URL.Path == "/v1/member/serving-proof" {
			body = mutateProof(body, config.ProofMutation)
		}
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("Content-Length", strconv.Itoa(len(body)))
		w.WriteHeader(code)
		w.Write(body)
	}))
}

func startMemberFixture(t *testing.T) *memberFixture {
	return startMemberFixtureNamespace(t, 0)
}

func startMemberFixtureNamespace(t *testing.T, namespaces uintptr) *memberFixture {
	t.Helper()
	directory, err := os.MkdirTemp("", "ts-member-")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		// Group write/execute permits unlinking the known socket, not listing.
		os.Remove(filepath.Join(directory, "control", "member.sock"))
		os.Remove(filepath.Join(directory, "control"))
		if err := os.RemoveAll(directory); err != nil {
			t.Error(err)
		}
	})
	uid, gid := os.Geteuid(), os.Getegid()
	if uid == 0 {
		uid, gid = 65534, 65534
	}
	if err := os.Chown(directory, uid, gid); err != nil {
		t.Fatal(err)
	}
	control := filepath.Join(directory, "control")
	if err := os.Mkdir(control, 0o730); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(control, 0o730); err != nil {
		t.Fatal(err)
	}
	if os.Geteuid() == 0 {
		err = os.Chown(control, 0, gid)
	} else {
		err = exec.Command("sudo", "-n", "chown", "0:"+strconv.Itoa(gid), control).Run()
	}
	if err != nil {
		t.Fatalf("root-owned control fixture requires root or passwordless sudo: %v", err)
	}
	fixture := &memberFixture{directory: directory}
	fixture.configure(t, fixtureConfig{})
	executable, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	// Root-owned go-build directories cannot be traversed by the member UID.
	binary := filepath.Join(directory, "fixture.test")
	contents, err := os.ReadFile(executable)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(binary, contents, 0o755); err != nil {
		t.Fatal(err)
	}
	fixture.process = exec.Command(binary, "-test.run=^$")
	fixture.process.Env = append(os.Environ(), "TS_MEMBER_PROTOCOL_FIXTURE="+directory)
	if os.Geteuid() == 0 {
		fixture.process.SysProcAttr = &syscall.SysProcAttr{Credential: &syscall.Credential{Uid: uint32(uid), Gid: uint32(gid)}, Cloneflags: namespaces}
	} else if namespaces != 0 {
		t.Fatal("real PID/mount namespace fixture requires root")
	}
	var logs bytes.Buffer
	fixture.process.Stderr = &logs
	if err := fixture.process.Start(); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		fixture.process.Process.Kill()
		fixture.process.Wait()
		if logs.Len() > 0 {
			t.Log(logs.String())
		}
	})
	socket := filepath.Join(control, "member.sock")
	deadline := time.Now().Add(5 * time.Second)
	for {
		if _, err := os.Stat(socket); err == nil {
			break
		}
		if time.Now().After(deadline) {
			t.Fatalf("member socket missing: %s", logs.String())
		}
		time.Sleep(5 * time.Millisecond)
	}
	identity := fixtureIdentity(fixture.process.Process.Pid)
	observe := func(context.Context) (ProcessObservation, error) {
		if namespaces != 0 {
			return ObserveContainerProcess(fixture.process.Process.Pid, fixture.process.Process.Pid)
		}
		return observeFixtureProcess(fixture.process.Process.Pid)
	}
	fixture.client, err = NewClient(socket, identity.Scope, identity.Authority, observe)
	if err != nil {
		t.Fatal(err)
	}
	state := filepath.Join(directory, "state")
	if err := os.Mkdir(state, 0o700); err != nil {
		t.Fatal(err)
	}
	fixture.store, err = NewFileStore(filepath.Join(state, "drain.json"))
	if err != nil {
		t.Fatal(err)
	}
	return fixture
}

func observeFixtureProcess(pid int) (ProcessObservation, error) {
	path := "/proc/" + strconv.Itoa(pid)
	info, err := os.Stat(path)
	if err != nil {
		return ProcessObservation{}, err
	}
	stat := info.Sys().(*syscall.Stat_t)
	raw, err := os.ReadFile(path + "/stat")
	if err != nil {
		return ProcessObservation{}, err
	}
	_, suffix, ok := strings.CutLast(string(raw), ") ")
	fields := strings.Fields(suffix)
	if !ok || len(fields) < 20 {
		return ProcessObservation{}, errors.New("invalid process stat")
	}
	cgroup, err := os.ReadFile(path + "/cgroup")
	if err != nil {
		return ProcessObservation{}, err
	}
	return ProcessObservation{PID: pid, UID: stat.Uid, GID: stat.Gid, KernelStart: fields[19], Cgroup: string(cgroup)}, nil
}
func (f *memberFixture) configure(t *testing.T, config fixtureConfig) {
	t.Helper()
	body, err := json.Marshal(config)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(f.directory, "config.json"), body, 0o644); err != nil {
		t.Fatal(err)
	}
}

func (f *memberFixture) restart(t *testing.T) {
	t.Helper()
	if err := f.process.Process.Kill(); err != nil {
		t.Fatal(err)
	}
	f.process.Wait()
	if err := os.Remove(f.client.socket); err != nil {
		t.Fatal(err)
	}
	process := exec.Command(f.process.Path, "-test.run=^$")
	process.Env, process.SysProcAttr, process.Stderr = f.process.Env, f.process.SysProcAttr, os.Stderr
	if err := process.Start(); err != nil {
		t.Fatal(err)
	}
	f.process = process
	deadline := time.Now().Add(5 * time.Second)
	for {
		if _, err := os.Stat(f.client.socket); err == nil {
			return
		}
		if time.Now().After(deadline) {
			t.Fatal("restarted member socket missing")
		}
		time.Sleep(5 * time.Millisecond)
	}
}

func (p ProcessObservation) ProtocolPID() int {
	if p.namespace.wirePID != 0 {
		return p.namespace.wirePID
	}
	return p.PID
}

// BindPIDNamespace derives the protocol PID from kernel observations rather
// than accepting a namespace PID asserted by a task or a caller.
func BindPIDNamespace(observation ProcessObservation, containerInitHostPID int) (ProcessObservation, error) {
	if observation.PID < 2 || containerInitHostPID < 2 {
		return ProcessObservation{}, ErrStaleBinding
	}
	current, ids, namespaces, err := readProcessNamespace(observation.PID)
	if err != nil || current.PID != observation.PID || current.UID != observation.UID || current.GID != observation.GID ||
		current.KernelStart != observation.KernelStart || current.Cgroup != observation.Cgroup || len(ids) < 2 {
		return ProcessObservation{}, ErrStaleBinding
	}
	init, initIDs, initNamespaces, err := readProcessNamespace(containerInitHostPID)
	if err != nil || len(initIDs) != len(ids) || initIDs[len(initIDs)-1] != 1 || namespaces != initNamespaces {
		return ProcessObservation{}, ErrStaleBinding
	}
	self, err := namespaceInodes(os.Getpid())
	if err != nil || namespaces[0] == self[0] || namespaces[1] == self[1] || namespaces[2] != self[2] {
		return ProcessObservation{}, ErrStaleBinding
	}
	observation.namespace = processNamespace{wirePID: ids[len(ids)-1], initPID: containerInitHostPID,
		pidNS: namespaces[0], mountNS: namespaces[1], userNS: namespaces[2], initStart: init.KernelStart}
	return observation, nil
}

func namespaceInodes(pid int) ([3]uint64, error) {
	var result [3]uint64
	for i, name := range []string{"pid", "mnt", "user"} {
		var stat unix.Stat_t
		if err := unix.Stat(fmt.Sprintf("/proc/%d/ns/%s", pid, name), &stat); err != nil {
			return result, err
		}
		result[i] = stat.Ino
	}
	return result, nil
}

// ObserveContainerProcess reads a host process and binds its namespace PID to
// the independently selected container init process.
func ObserveContainerProcess(hostPID, containerInitHostPID int) (ProcessObservation, error) {
	observation, _, _, err := readProcessNamespace(hostPID)
	if err != nil {
		return ProcessObservation{}, err
	}
	bound, err := BindPIDNamespace(observation, containerInitHostPID)
	if err != nil {
		return ProcessObservation{}, err
	}
	after, err := BindPIDNamespace(observation, containerInitHostPID)
	if err != nil || bound != after {
		return ProcessObservation{}, ErrStaleBinding
	}
	return bound, nil
}

func readProcessNamespace(pid int) (ProcessObservation, []int, [3]uint64, error) {
	result := ProcessObservation{PID: pid}
	var namespaces [3]uint64
	if pid < 2 {
		return result, nil, namespaces, ErrStaleBinding
	}
	root := fmt.Sprintf("/proc/%d/", pid)
	stat, err := os.ReadFile(root + "stat")
	if err != nil {
		return result, nil, namespaces, err
	}
	_, suffix, ok := strings.CutLast(string(stat), ") ")
	fields := strings.Fields(suffix)
	if !ok || len(fields) < 20 || fields[0] == "Z" || fields[0] == "X" {
		return result, nil, namespaces, ErrStaleBinding
	}
	result.KernelStart = fields[19]
	status, err := os.ReadFile(root + "status")
	if err != nil {
		return result, nil, namespaces, err
	}
	var ids []int
	uidFound, gidFound := false, false
	for line := range strings.SplitSeq(string(status), "\n") {
		name, values, ok := strings.Cut(line, ":")
		if !ok || (name != "Uid" && name != "Gid" && name != "NSpid") {
			continue
		}
		values = strings.TrimSpace(values)
		for i, value := range strings.Fields(values) {
			number, err := strconv.ParseUint(value, 10, 32)
			if err != nil {
				return result, nil, namespaces, ErrStaleBinding
			}
			if name == "NSpid" {
				if number == 0 {
					return result, nil, namespaces, ErrStaleBinding
				}
				ids = append(ids, int(number))
			} else if name == "Uid" {
				if i > 0 && result.UID != uint32(number) {
					return result, nil, namespaces, ErrStaleBinding
				}
				result.UID, uidFound = uint32(number), true
			} else {
				if i > 0 && result.GID != uint32(number) {
					return result, nil, namespaces, ErrStaleBinding
				}
				result.GID, gidFound = uint32(number), true
			}
		}
	}
	if !uidFound || !gidFound || len(ids) == 0 || ids[0] != pid {
		return result, nil, namespaces, ErrStaleBinding
	}
	cgroup, err := os.ReadFile(root + "cgroup")
	if err != nil || len(cgroup) == 0 {
		return result, nil, namespaces, ErrStaleBinding
	}
	result.Cgroup = string(cgroup)
	namespaces, err = namespaceInodes(pid)
	return result, ids, namespaces, err
}

func NewClient(socket string, scope Scope, authority Authority, observe ObserveProcess) (*Client, error) {
	if socket == "" || !filepath.IsAbs(socket) || filepath.Clean(socket) != socket ||
		!scope.valid() || !authority.valid() || observe == nil {
		return nil, errors.New("incomplete signed member control binding")
	}
	return &Client{socket: socket, scope: scope, authority: authority, observe: observe}, nil
}

func nonce() (string, error) {
	var value [16]byte
	if _, err := rand.Read(value[:]); err != nil {
		return "", fmt.Errorf("member challenge: %w", err)
	}
	return hex.EncodeToString(value[:]), nil
}

func (c *Client) Status(ctx context.Context) (Status, error) {
	challenge, err := nonce()
	if err != nil {
		return Status{}, err
	}
	code, body, process, err := c.exchange(ctx, http.MethodGet, "/v1/member/status?nonce="+challenge, nil)
	if err != nil {
		return Status{}, err
	}
	if code != http.StatusOK {
		return Status{}, fmt.Errorf("member status HTTP %d", code)
	}
	// The load block is telemetry, never evidence: it is split off before
	// the strict decode, and a malformed, incomplete or out-of-range block
	// is dropped instead of failing the status.
	evidence, load := SplitLoad(body)
	var status Status
	if err := decodeRequired(evidence, &status, statusPaths...); err != nil {
		return Status{}, err
	}
	status.Load = DecodeLoad(load)
	if status.SchemaVersion != 2 || status.Nonce != challenge || status.Process.PID != process.ProtocolPID() ||
		!status.Process.valid() || status.Scope != c.scope || status.Authority != c.authority ||
		!status.Capabilities.ServingProof || !status.Capabilities.DurableDrain {
		return Status{}, ErrStaleBinding
	}
	if status.Serving && (status.ReceiverOnly || !status.Local.StorageRecovered ||
		!status.Local.ReplicationListenerReady || !status.Local.Healthy || !status.Local.Ready) {
		return Status{}, ErrNotServing
	}
	status.verified = true
	return status, nil
}

// ServingProof requires a fresh status from this exact process and a named,
// signed survivor. The remote ACK and root coverage checks use typed fields;
// caller-provided health booleans cannot satisfy them.
func (c *Client) ServingProof(ctx context.Context, status Status, survivor Survivor) (ServingProof, error) {
	if !survivor.valid() {
		return ServingProof{}, ErrNotServing
	}
	return c.servingProof(ctx, status, survivor.MemberID, survivor.Incarnation)
}

// ServingProofForPeer binds the signed peer member ID at the host. The
// controller must compare the returned incarnation with its signed roster.
func (c *Client) ServingProofForPeer(ctx context.Context, status Status, peerMemberID string) (ServingProof, error) {
	return c.servingProof(ctx, status, peerMemberID, "")
}

func (c *Client) servingProof(ctx context.Context, status Status, peerMemberID, peerIncarnation string) (ServingProof, error) {
	if !status.verified || !canonicalID(peerMemberID) || peerMemberID == c.scope.MemberID ||
		status.Scope != c.scope || status.Authority != c.authority || !status.Process.valid() ||
		status.ReceiverOnly || !status.Serving || !status.Local.StorageRecovered ||
		!status.Local.ReplicationListenerReady || !status.Local.Healthy || !status.Local.Ready {
		return ServingProof{}, ErrNotServing
	}
	challenge, err := nonce()
	if err != nil {
		return ServingProof{}, err
	}
	code, body, process, err := c.exchange(ctx, http.MethodGet, "/v1/member/serving-proof?nonce="+challenge, nil)
	if err != nil {
		return ServingProof{}, err
	}
	if code == http.StatusServiceUnavailable {
		return ServingProof{}, ErrNotServing
	}
	if code != http.StatusOK {
		return ServingProof{}, fmt.Errorf("member serving proof HTTP %d", code)
	}
	proof, err := decodeServingProof(body)
	if err != nil {
		return ServingProof{}, err
	}
	if proof.SchemaVersion != 1 || proof.Nonce != challenge || proof.Process != status.Process ||
		proof.Process.PID != process.ProtocolPID() || proof.Scope != c.scope || proof.Authority != c.authority ||
		!proof.Serving || !proof.Listeners.Client || !proof.Listeners.Replication ||
		!lowerHex(proof.Object.RootSHA256, 64) || !lowerHex(proof.Object.TargetSHA256, 64) ||
		!lowerHex(proof.Object.InboxArchiveSHA256AtRecovery, 64) ||
		proof.Object.RemoteAppliedSequence > proof.Object.RemoteInboxDurableSequence ||
		proof.Replication.PeerMemberID != peerMemberID || !lowerHexIdentity(proof.Replication.PeerIncarnation) ||
		peerIncarnation != "" && proof.Replication.PeerIncarnation != peerIncarnation ||
		!proof.Replication.CurrentAuthenticated ||
		proof.Replication.LocalSourceSequence != proof.Object.LocalSourceSequence ||
		proof.Replication.PeerAppliedSequence < proof.Replication.LocalSourceSequence ||
		!proof.Replication.ordered() {
		return ServingProof{}, ErrNotServing
	}
	proof.verified = true
	return proof, nil
}

func inspectSocket(path string, process ProcessObservation) (socketSnapshot, error) {
	parentInfo, err := os.Lstat(filepath.Dir(path))
	if err != nil {
		return socketSnapshot{}, err
	}
	socketInfo, err := os.Lstat(path)
	if err != nil {
		return socketSnapshot{}, err
	}
	parent, parentOK := parentInfo.Sys().(*syscall.Stat_t)
	socket, socketOK := socketInfo.Sys().(*syscall.Stat_t)
	if !parentOK || !socketOK || !parentInfo.IsDir() || socketInfo.Mode()&os.ModeSocket == 0 ||
		parent.Uid != 0 || parent.Gid != process.GID || parent.Mode&0o7777 != 0o730 ||
		socket.Uid != process.UID || socket.Gid != process.GID || socket.Mode&0o7777 != 0o602 {
		return socketSnapshot{}, errors.New("unsafe member control socket ownership or mode")
	}
	return socketSnapshot{parent: *parent, socket: *socket}, nil
}

func (s socketSnapshot) same(other socketSnapshot) bool {
	return sameInode(s.parent, other.parent) && sameInode(s.socket, other.socket)
}

func sameInode(a, b syscall.Stat_t) bool {
	return a.Dev == b.Dev && a.Ino == b.Ino && a.Mode == b.Mode && a.Uid == b.Uid && a.Gid == b.Gid
}

func (c *Client) exchange(ctx context.Context, method, path string, requestBody []byte) (int, []byte, ProcessObservation, error) {
	return c.exchangeBounded(ctx, method, path, requestBody, maxEvidenceBytes, 3*time.Second)
}

func (c *Client) exchangeBounded(ctx context.Context, method, path string, requestBody []byte,
	maxResponse int64, timeout time.Duration,
) (int, []byte, ProcessObservation, error) {
	if maxResponse <= 0 || maxResponse > 64<<10 || len(requestBody) > 64<<10 {
		return 0, nil, ProcessObservation{}, errors.New("member control request or response bound is invalid")
	}
	ctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	before, err := c.observe(ctx)
	if err != nil {
		return 0, nil, ProcessObservation{}, fmt.Errorf("unverified native member process: %w", err)
	}
	if before.PID < 2 || before.UID == 0 || before.GID == 0 || before.KernelStart == "" || before.Cgroup == "" {
		return 0, nil, ProcessObservation{}, errors.New("unverified native member process")
	}
	if before.namespace.wirePID != 0 {
		bound, err := BindPIDNamespace(before, before.namespace.initPID)
		if err != nil || bound != before {
			return 0, nil, ProcessObservation{}, ErrStaleBinding
		}
	}
	pathBefore, err := inspectSocket(c.socket, before)
	if err != nil {
		return 0, nil, ProcessObservation{}, err
	}
	var peerPID atomic.Int64
	transport := &http.Transport{
		DisableKeepAlives: true, DisableCompression: true, MaxResponseHeaderBytes: 4096,
		DialContext: func(dialCtx context.Context, _, _ string) (net.Conn, error) {
			conn, err := (&net.Dialer{}).DialContext(dialCtx, "unix", c.socket)
			if err != nil {
				return nil, err
			}
			credentials, err := peerCredentials(conn)
			if err == nil && (credentials.Pid != int32(before.PID) || credentials.Uid != before.UID || credentials.Gid != before.GID) {
				err = ErrStaleBinding
			}
			if err == nil {
				var current socketSnapshot
				current, err = inspectSocket(c.socket, before)
				if err == nil && !pathBefore.same(current) {
					err = ErrStaleBinding
				}
			}
			if err != nil {
				_ = conn.Close()
				return nil, err
			}
			peerPID.Store(int64(credentials.Pid))
			return conn, nil
		},
	}
	defer transport.CloseIdleConnections()
	request, err := http.NewRequestWithContext(ctx, method, "http://unix"+path, bytes.NewReader(requestBody))
	if err != nil {
		return 0, nil, ProcessObservation{}, err
	}
	if method == http.MethodPost {
		request.Header.Set("Content-Type", "application/json")
	}
	response, err := (&http.Client{Transport: transport, CheckRedirect: func(*http.Request, []*http.Request) error {
		return http.ErrUseLastResponse
	}}).Do(request)
	if err != nil {
		return 0, nil, ProcessObservation{}, fmt.Errorf("member control request: %w", err)
	}
	defer response.Body.Close()
	if response.Header.Get("Content-Type") != "application/json" || response.ContentLength < 0 ||
		response.ContentLength > maxResponse || len(response.TransferEncoding) != 0 {
		return 0, nil, ProcessObservation{}, errors.New("invalid member control HTTP response")
	}
	body, err := io.ReadAll(io.LimitReader(response.Body, maxResponse+1))
	if err != nil || len(body) != int(response.ContentLength) || int64(len(body)) > maxResponse {
		return 0, nil, ProcessObservation{}, errors.New("invalid member control response length")
	}
	if peerPID.Load() != int64(before.PID) {
		return 0, nil, ProcessObservation{}, ErrStaleBinding
	}
	pathAfter, err := inspectSocket(c.socket, before)
	if err != nil || !pathBefore.same(pathAfter) {
		return 0, nil, ProcessObservation{}, ErrStaleBinding
	}
	after, err := c.observe(ctx)
	if err != nil || after != before {
		return 0, nil, ProcessObservation{}, ErrStaleBinding
	}
	return response.StatusCode, body, before, nil
}

func peerCredentials(conn net.Conn) (*unix.Ucred, error) {
	unixConn, ok := conn.(*net.UnixConn)
	if !ok {
		return nil, errors.New("member control connection is not Unix")
	}
	raw, err := unixConn.SyscallConn()
	if err != nil {
		return nil, err
	}
	var credentials *unix.Ucred
	var readErr error
	if err := raw.Control(func(fd uintptr) {
		credentials, readErr = unix.GetsockoptUcred(int(fd), unix.SOL_SOCKET, unix.SO_PEERCRED)
	}); err != nil {
		return nil, err
	}
	return credentials, readErr
}

func decodeServingProof(body []byte) (ServingProof, error) {
	var proof ServingProof
	if err := decodeRequired(body, &proof, servingPaths...); err != nil {
		return ServingProof{}, err
	}
	if err := rejectNull(body, servingOptionalPaths...); err != nil {
		return ServingProof{}, err
	}
	return proof, nil
}

func encodeRequest(request DrainRequest) ([]byte, error) { return json.Marshal(request) }

func (s Scope) valid() bool {
	return lowerHexIdentity(s.ClusterID) && lowerHexIdentity(s.Incarnation) && s.ShardID != 0 &&
		canonicalID(s.TenantID) && canonicalID(s.DatabaseID) && canonicalID(s.MemberID)
}

func (a Authority) valid() bool {
	return a.Epoch != 0 && lowerHex(a.ConfigurationID, 64) &&
		lowerHex(a.CertificateSHA256, 64) && lowerHex(a.TLSLeafSHA256, 64)
}

func (p Process) valid() bool { return p.PID >= 1 && lowerHex(p.StartNonce, 32) }

func (s Survivor) valid() bool {
	return canonicalID(s.MemberID) && lowerHexIdentity(s.Incarnation)
}

func lowerHex(value string, length int) bool {
	if len(value) != length {
		return false
	}
	for i := range len(value) {
		if value[i] < '0' || value[i] > '9' {
			if value[i] < 'a' || value[i] > 'f' {
				return false
			}
		}
	}
	return true
}

func canonicalID(value string) bool { return entityid.Valid(value) }

// decodeRequired rejects duplicate, unknown, null, and absent contract fields.
func decodeRequired(data []byte, into any, paths ...string) error {
	if err := json.Unmarshal(data, into, json.RejectUnknownMembers(true)); err != nil {
		return fmt.Errorf("decode member evidence: %w", err)
	}
	var root map[string]any
	if err := json.Unmarshal(data, &root); err != nil {
		return fmt.Errorf("decode member fields: %w", err)
	}
	for _, path := range paths {
		current := any(root)
		for _, part := range splitPath(path) {
			object, ok := current.(map[string]any)
			if !ok {
				return fmt.Errorf("member evidence omits %s", path)
			}
			current, ok = object[part]
			if !ok || current == nil {
				return fmt.Errorf("member evidence omits %s", path)
			}
		}
	}
	return nil
}

// rejectNull rejects an explicit JSON null at any present optional path.
func rejectNull(data []byte, paths ...string) error {
	var root map[string]any
	if err := json.Unmarshal(data, &root); err != nil {
		return fmt.Errorf("decode member fields: %w", err)
	}
	for _, path := range paths {
		current, present := any(root), true
		for _, part := range splitPath(path) {
			object, ok := current.(map[string]any)
			if !ok {
				present = false
				break
			}
			if current, ok = object[part]; !ok {
				present = false
				break
			}
		}
		if present && current == nil {
			return fmt.Errorf("member evidence has null %s", path)
		}
	}
	return nil
}

func requirePresent(data []byte, paths ...string) error {
	var root map[string]any
	if err := json.Unmarshal(data, &root); err != nil {
		return err
	}
	for _, path := range paths {
		current := any(root)
		for _, part := range splitPath(path) {
			object, ok := current.(map[string]any)
			if !ok {
				return fmt.Errorf("member evidence omits %s", path)
			}
			current, ok = object[part]
			if !ok {
				return fmt.Errorf("member evidence omits %s", path)
			}
		}
	}
	return nil
}

func splitPath(path string) []string {
	return strings.Split(path, ".")
}

func (r DrainReceipt) digest() (string, error) {
	data, err := json.Marshal(r)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:]), nil
}

var ErrNotServing = errors.New("member is not serving with current proof")
var ErrStaleBinding = errors.New("member process or authority binding changed")
var ErrOperationConflict = errors.New("member drain operation conflicts with persisted intent")
var ErrOutcomeUnknown = errors.New("member drain outcome requires reconciliation")

func lowerHexIdentity(value string) bool {
	return lowerHex(value, 32) && strings.Trim(value, "0") != ""
}

func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

func (c *Client) Drain(ctx context.Context, survivor Survivor, operationID string, store DrainStore) (DrainEnvelope, error) {
	if store == nil {
		return DrainEnvelope{}, errors.New("member drain has no durable store")
	}
	record, found, err := store.Load()
	if err != nil {
		return DrainEnvelope{}, err
	}
	if found {
		if !record.valid(c.scope, c.authority) || record.Request.OperationID != operationID || record.Survivor != survivor {
			return DrainEnvelope{}, ErrOperationConflict
		}
	} else {
		status, err := c.Status(ctx)
		if err != nil {
			return DrainEnvelope{}, err
		}
		proof, err := c.ServingProof(ctx, status, survivor)
		if err != nil {
			return DrainEnvelope{}, err
		}
		if _, err := c.PrepareDrain(status, proof, survivor, operationID, store); err != nil {
			return DrainEnvelope{}, err
		}
	}
	return c.ReconcileDrain(ctx, store)
}

// PrepareDrain saves an exact idempotent request only after a live serving
// proof names the required survivor and its applied ACK covers the source.
func (c *Client) PrepareDrain(status Status, proof ServingProof, survivor Survivor, operationID string, store DrainStore) (DrainRecord, error) {
	if store == nil || !status.verified || !proof.verified || !entityid.Valid(operationID) || !survivor.valid() ||
		status.Process != proof.Process || status.Scope != proof.Scope || status.Authority != proof.Authority ||
		status.Scope != c.scope || status.Authority != c.authority || status.ReceiverOnly || !status.Serving ||
		proof.Replication.PeerMemberID != survivor.MemberID || proof.Replication.PeerIncarnation != survivor.Incarnation ||
		proof.Replication.PeerAppliedSequence < proof.Replication.LocalSourceSequence ||
		proof.Replication.PeerDurableSequence < proof.Replication.PeerAppliedSequence ||
		proof.Object.LocalSourceSequence != proof.Replication.LocalSourceSequence {
		return DrainRecord{}, ErrNotServing
	}
	challenge, err := nonce()
	if err != nil {
		return DrainRecord{}, err
	}
	record := DrainRecord{
		Request: DrainRequest{
			SchemaVersion: 1, OperationID: operationID, Nonce: challenge,
			Expected: Identity{Process: status.Process, Scope: c.scope, Authority: c.authority},
		},
		Survivor: survivor, SourceSequence: proof.Replication.LocalSourceSequence,
	}
	if err := store.Create(record); err != nil {
		return DrainRecord{}, fmt.Errorf("persist member drain request: %w", err)
	}
	return record, nil
}

// ReconcileDrain polls the Rust operation first. A 404 can be retried with
// the exact persisted POST only while the original process is still current.
// An ambiguous transport result remains unknown until a later status poll.
func (c *Client) ReconcileDrain(ctx context.Context, store DrainStore) (DrainEnvelope, error) {
	if store == nil {
		return DrainEnvelope{}, errors.New("member drain has no durable store")
	}
	record, found, err := store.Load()
	if err != nil {
		return DrainEnvelope{}, err
	}
	if !found || !record.valid(c.scope, c.authority) {
		return DrainEnvelope{}, ErrStaleBinding
	}
	status, err := c.Status(ctx)
	if err != nil {
		return DrainEnvelope{}, err
	}
	observation, code, err := c.drainStatus(ctx, record, status)
	if err != nil {
		return DrainEnvelope{}, errors.Join(ErrOutcomeUnknown, err)
	}
	if code != http.StatusNotFound {
		return observation, nil
	}
	if status.Process != record.Request.Expected.Process {
		return DrainEnvelope{}, ErrOutcomeUnknown
	}
	body, err := encodeRequest(record.Request)
	if err != nil {
		return DrainEnvelope{}, err
	}
	code, response, observed, err := c.exchange(ctx, http.MethodPost, "/v1/member/drain", body)
	if err != nil {
		return DrainEnvelope{}, errors.Join(ErrOutcomeUnknown, err)
	}
	if observed.ProtocolPID() != status.Process.PID {
		return DrainEnvelope{}, ErrStaleBinding
	}
	switch code {
	case http.StatusOK, http.StatusAccepted:
		return validateDrainEnvelope(response, code, record.Request.Nonce, status, record)
	case http.StatusConflict:
		return DrainEnvelope{}, ErrOperationConflict
	case http.StatusPreconditionFailed:
		// A process switch or an uncertain earlier POST can race the 404. Poll
		// again before classifying; never construct a new request in this path.
		current, statusErr := c.Status(ctx)
		if statusErr != nil {
			return DrainEnvelope{}, errors.Join(ErrOutcomeUnknown, statusErr)
		}
		observation, pollCode, pollErr := c.drainStatus(ctx, record, current)
		if pollErr == nil && pollCode != http.StatusNotFound {
			return observation, nil
		}
		return DrainEnvelope{}, ErrStaleBinding
	default:
		return DrainEnvelope{}, fmt.Errorf("member drain HTTP %d: %w", code, ErrOutcomeUnknown)
	}
}

func (c *Client) drainStatus(ctx context.Context, record DrainRecord, current Status) (DrainEnvelope, int, error) {
	challenge, err := nonce()
	if err != nil {
		return DrainEnvelope{}, 0, err
	}
	path := "/v1/member/drain-status?operation_id=" + record.Request.OperationID + "&nonce=" + challenge
	code, body, process, err := c.exchange(ctx, http.MethodGet, path, nil)
	if err != nil {
		return DrainEnvelope{}, 0, err
	}
	if process.ProtocolPID() != current.Process.PID {
		return DrainEnvelope{}, 0, ErrStaleBinding
	}
	if code == http.StatusNotFound {
		return DrainEnvelope{}, code, nil
	}
	if code != http.StatusOK && code != http.StatusAccepted {
		return DrainEnvelope{}, code, fmt.Errorf("member drain status HTTP %d", code)
	}
	observation, err := validateDrainEnvelope(body, code, challenge, current, record)
	return observation, code, err
}

func (r DrainRecord) valid(scope Scope, authority Authority) bool {
	return r.Request.SchemaVersion == 1 && entityid.Valid(r.Request.OperationID) && lowerHex(r.Request.Nonce, 32) &&
		r.Request.Expected.Process.valid() && r.Request.Expected.Scope == scope && r.Request.Expected.Authority == authority &&
		r.Survivor.valid() && r.Survivor.MemberID != scope.MemberID
}

func validateDrainEnvelope(body []byte, code int, challenge string, current Status, record DrainRecord) (DrainEnvelope, error) {
	var envelope DrainEnvelope
	if err := decodeRequired(body, &envelope, drainEnvelopePaths...); err != nil {
		return DrainEnvelope{}, err
	}
	if err := requirePresent(body, "receipt_sha256", "receipt"); err != nil {
		return DrainEnvelope{}, err
	}
	if envelope.SchemaVersion != 1 || envelope.Nonce != challenge || envelope.OperationID != record.Request.OperationID ||
		envelope.Process != current.Process {
		return DrainEnvelope{}, ErrStaleBinding
	}
	if envelope.State == "pending" && code == http.StatusAccepted && envelope.Receipt == nil && envelope.ReceiptSHA256 == nil {
		return envelope, nil
	}
	if envelope.State != "complete" || code != http.StatusOK || envelope.Receipt == nil || envelope.ReceiptSHA256 == nil ||
		!lowerHex(*envelope.ReceiptSHA256, 64) {
		return DrainEnvelope{}, errors.New("inconsistent member drain state")
	}
	var required map[string]any
	if err := json.Unmarshal(body, &required); err != nil {
		return DrainEnvelope{}, err
	}
	if err := requireReceiptFields(required); err != nil {
		return DrainEnvelope{}, err
	}
	receipt := envelope.Receipt
	digest, err := receipt.digest()
	if err != nil || digest != *envelope.ReceiptSHA256 || receipt.SchemaVersion != 1 ||
		receipt.OperationID != record.Request.OperationID || receipt.RequestNonce != record.Request.Nonce ||
		receipt.RequestedProcess != record.Request.Expected.Process || !receipt.DrainedProcess.valid() ||
		receipt.Scope != record.Request.Expected.Scope || receipt.Authority != record.Request.Expected.Authority ||
		receipt.LocalSourceOrigin != (Origin{MemberID: receipt.Scope.MemberID, Incarnation: receipt.Scope.Incarnation}) ||
		receipt.LocalSourceDurableSequence < record.SourceSequence ||
		receipt.ArchivedSourceSequence != receipt.LocalSourceDurableSequence ||
		!lowerHex(receipt.ObjectRootSHA256, 64) ||
		receipt.Peer.Origin != (Origin{MemberID: record.Survivor.MemberID, Incarnation: record.Survivor.Incarnation}) ||
		receipt.Peer.DurableSequence < receipt.LocalSourceDurableSequence ||
		receipt.Peer.AppliedSequence < receipt.LocalSourceDurableSequence ||
		receipt.Peer.AppliedSequence > receipt.Peer.DurableSequence ||
		receipt.Peer.LocalInboxAppliedSequence > receipt.Peer.LocalInboxDurableSequence ||
		!receipt.ReplicationQuiesced {
		return DrainEnvelope{}, errors.New("member drain receipt violates signed survivor or root frontier")
	}
	envelope.verified = true
	return envelope, nil
}

var drainEnvelopePaths = []string{
	"schema_version", "nonce", "process.pid", "process.start_nonce", "operation_id", "state",
}

func requireReceiptFields(root map[string]any) error {
	paths := []string{
		"receipt_sha256", "receipt.schema_version", "receipt.operation_id", "receipt.request_nonce",
		"receipt.requested_process.pid", "receipt.requested_process.start_nonce",
		"receipt.drained_process.pid", "receipt.drained_process.start_nonce",
		"receipt.scope.cluster_id", "receipt.scope.tenant_id", "receipt.scope.database_id", "receipt.scope.shard_id",
		"receipt.scope.member_id", "receipt.scope.incarnation",
		"receipt.authority.epoch", "receipt.authority.configuration_id", "receipt.authority.certificate_sha256", "receipt.authority.tls_leaf_sha256",
		"receipt.local_source_origin.member_id", "receipt.local_source_origin.incarnation",
		"receipt.local_source_durable_sequence", "receipt.archived_source_sequence", "receipt.object_root_sha256",
		"receipt.peer.origin.member_id", "receipt.peer.origin.incarnation", "receipt.peer.durable_sequence", "receipt.peer.applied_sequence",
		"receipt.peer.local_inbox_durable_sequence", "receipt.peer.local_inbox_applied_sequence", "receipt.replication_quiesced",
	}
	for _, path := range paths {
		current := any(root)
		for _, part := range splitPath(path) {
			object, ok := current.(map[string]any)
			if !ok {
				return fmt.Errorf("member drain omits %s", path)
			}
			current, ok = object[part]
			if !ok || current == nil {
				return fmt.Errorf("member drain omits %s", path)
			}
		}
	}
	return nil
}

func NewFileStore(path string) (*FileStore, error) {
	if path == "" || !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return nil, errors.New("member drain record path must be absolute and clean")
	}
	dir, err := os.Lstat(filepath.Dir(path))
	if err != nil {
		return nil, err
	}
	stat, ok := dir.Sys().(*syscall.Stat_t)
	if !ok || !dir.IsDir() || stat.Uid != uint32(os.Geteuid()) || dir.Mode().Perm() != 0o700 {
		return nil, errors.New("member drain record directory ownership or mode is unsafe")
	}
	return &FileStore{path: path}, nil
}

func (s *FileStore) Load() (DrainRecord, bool, error) {
	var record DrainRecord
	var found bool
	err := s.locked(func() error {
		var err error
		record, found, err = s.loadUnlocked()
		return err
	})
	return record, found, err
}

func (s *FileStore) Create(record DrainRecord) error {
	if !record.valid(record.Request.Expected.Scope, record.Request.Expected.Authority) {
		return ErrStaleBinding
	}
	return s.locked(func() error {
		current, found, err := s.loadUnlocked()
		if err != nil {
			return err
		}
		if found {
			if current != record {
				return ErrOperationConflict
			}
			return nil
		}
		data, err := json.Marshal(record)
		if err != nil {
			return err
		}
		if len(data) > maxRecordBytes {
			return errors.New("member drain record exceeds bound")
		}
		directory := filepath.Dir(s.path)
		temp, err := os.CreateTemp(directory, ".member-drain-*")
		if err != nil {
			return err
		}
		defer os.Remove(temp.Name())
		if err := temp.Chmod(0o600); err != nil {
			_ = temp.Close()
			return err
		}
		if _, err := temp.Write(data); err != nil {
			_ = temp.Close()
			return err
		}
		if err := temp.Sync(); err != nil {
			_ = temp.Close()
			return err
		}
		if err := temp.Close(); err != nil {
			return err
		}
		if err := os.Rename(temp.Name(), s.path); err != nil {
			return err
		}
		dir, err := os.Open(directory)
		if err != nil {
			return err
		}
		defer dir.Close()
		return dir.Sync()
	})
}

func (s *FileStore) loadUnlocked() (DrainRecord, bool, error) {
	info, err := os.Lstat(s.path)
	if errors.Is(err, os.ErrNotExist) {
		return DrainRecord{}, false, nil
	}
	if err != nil {
		return DrainRecord{}, false, err
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.Mode().IsRegular() || stat.Nlink != 1 || stat.Uid != uint32(os.Geteuid()) || info.Mode().Perm() != 0o600 || info.Size() > maxRecordBytes {
		return DrainRecord{}, false, errors.New("unsafe member drain record")
	}
	file, err := os.Open(s.path)
	if err != nil {
		return DrainRecord{}, false, err
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, maxRecordBytes+1))
	if err != nil || len(data) > maxRecordBytes {
		return DrainRecord{}, false, errors.New("invalid member drain record length")
	}
	var record DrainRecord
	if err := decodeRequired(data, &record, "request.schema_version", "request.operation_id", "request.nonce",
		"request.expected.process.pid", "request.expected.process.start_nonce",
		"request.expected.scope.cluster_id", "request.expected.scope.tenant_id", "request.expected.scope.database_id",
		"request.expected.scope.shard_id", "request.expected.scope.member_id", "request.expected.scope.incarnation",
		"request.expected.authority.epoch", "request.expected.authority.configuration_id",
		"request.expected.authority.certificate_sha256", "request.expected.authority.tls_leaf_sha256",
		"survivor.member_id", "survivor.incarnation", "source_sequence"); err != nil {
		return DrainRecord{}, false, err
	}
	if !record.valid(record.Request.Expected.Scope, record.Request.Expected.Authority) {
		return DrainRecord{}, false, ErrStaleBinding
	}
	return record, true, nil
}

func (s *FileStore) locked(action func() error) error {
	lock, err := os.OpenFile(s.path+".lock", os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		return err
	}
	defer lock.Close()
	info, err := lock.Stat()
	if err != nil {
		return err
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.Mode().IsRegular() || stat.Nlink != 1 || stat.Uid != uint32(os.Geteuid()) || info.Mode().Perm() != 0o600 {
		return errors.New("unsafe member drain lock")
	}
	if err := unix.Flock(int(lock.Fd()), unix.LOCK_EX); err != nil {
		return fmt.Errorf("lock member drain: %w", err)
	}
	defer unix.Flock(int(lock.Fd()), unix.LOCK_UN)
	return action()
}

func (s *FileStore) RetainComplete(envelope DrainEnvelope) error {
	if !envelope.verified {
		return ErrOutcomeUnknown
	}
	return s.locked(func() error {
		record, found, err := s.loadUnlocked()
		if err != nil || !found {
			return errors.Join(ErrStaleBinding, err)
		}
		wire, err := json.Marshal(envelope)
		if err != nil || len(wire) > maxEvidenceBytes {
			return errors.Join(ErrOutcomeUnknown, err)
		}
		if _, err := validateDrainEnvelope(wire, http.StatusOK, envelope.Nonce, Status{Process: envelope.Process}, record); err != nil {
			return err
		}
		if current, found, err := s.readCompleteUnlocked(record); err != nil {
			return err
		} else if found {
			if current.ReceiptSHA256 == nil || envelope.ReceiptSHA256 == nil || *current.ReceiptSHA256 != *envelope.ReceiptSHA256 {
				return ErrOperationConflict
			}
			return nil
		}
		file, err := os.CreateTemp(filepath.Dir(s.path), ".member-complete-*")
		if err != nil {
			return err
		}
		defer os.Remove(file.Name())
		if err := file.Chmod(0o600); err != nil {
			file.Close()
			return err
		}
		if _, err := file.Write(wire); err != nil {
			file.Close()
			return err
		}
		if err := file.Sync(); err != nil {
			file.Close()
			return err
		}
		if err := file.Close(); err != nil {
			return err
		}
		if err := os.Rename(file.Name(), s.path+".complete"); err != nil {
			return err
		}
		directory, err := os.Open(filepath.Dir(s.path))
		if err != nil {
			return err
		}
		defer directory.Close()
		return directory.Sync()
	})
}

// ReadComplete authenticates the retained receipt against the original durable
// request and survivor frontier without querying a process that has stopped.
func (s *FileStore) ReadComplete() (DrainEnvelope, bool, error) {
	var envelope DrainEnvelope
	var found bool
	err := s.locked(func() error {
		record, present, err := s.loadUnlocked()
		if err != nil {
			return err
		}
		if !present {
			return nil
		}
		envelope, found, err = s.readCompleteUnlocked(record)
		return err
	})
	return envelope, found, err
}

func (s *FileStore) readCompleteUnlocked(record DrainRecord) (DrainEnvelope, bool, error) {
	path := s.path + ".complete"
	before, err := os.Lstat(path)
	if errors.Is(err, os.ErrNotExist) {
		return DrainEnvelope{}, false, nil
	}
	if err != nil {
		return DrainEnvelope{}, false, err
	}
	stat, ok := before.Sys().(*syscall.Stat_t)
	if !ok || !before.Mode().IsRegular() || stat.Uid != uint32(os.Geteuid()) || before.Mode().Perm() != 0o600 || before.Size() <= 0 || before.Size() > maxEvidenceBytes {
		return DrainEnvelope{}, false, errors.New("unsafe retained member drain receipt")
	}
	wire, err := os.ReadFile(path)
	if err != nil {
		return DrainEnvelope{}, false, err
	}
	after, err := os.Lstat(path)
	if err != nil || !os.SameFile(before, after) || int64(len(wire)) != before.Size() {
		return DrainEnvelope{}, false, ErrStaleBinding
	}
	var envelope DrainEnvelope
	if err := json.Unmarshal(wire, &envelope, json.RejectUnknownMembers(true)); err != nil {
		return DrainEnvelope{}, false, err
	}
	verified, err := validateDrainEnvelope(wire, http.StatusOK, envelope.Nonce, Status{Process: envelope.Process}, record)
	if err != nil {
		return DrainEnvelope{}, false, fmt.Errorf("retained final drain receipt: %w", err)
	}
	return verified, true, nil
}

func (l Load) Validate() error {
	if l.Connections > MaxLoadConnections || l.StorageBytes > MaxLoadStorageBytes ||
		l.ReplicationLagSeq > MaxLoadLagSeq || math.IsNaN(l.WriteQPS) || math.IsInf(l.WriteQPS, 0) ||
		l.WriteQPS < 0 || l.WriteQPS > MaxLoadWriteQPS {
		return ErrInvalidLoad
	}
	return nil
}

// loadFields are the counters a load block must carry; a missing counter
// never reads as zero load.
var loadFields = []string{"connections", "storage_bytes", "replication_lag_seq", "write_qps"}

// DecodeLoad parses a raw load block. Any problem (malformed JSON, a value
// of the wrong type or out of range such as a negative counter or 1e400, a
// missing counter, an unknown member, or null) yields nil instead of an
// error: the block is telemetry, never evidence, so it can never fail the
// status that carries it, and a newer TerraBase that adds a counter only
// loses its telemetry until this build learns the field.
func DecodeLoad(raw []byte) *Load {
	if len(raw) == 0 {
		return nil
	}
	var load Load
	if decodeRequired(raw, &load, loadFields...) != nil || load.Validate() != nil {
		return nil
	}
	return &load
}

// SplitLoad removes the optional top-level "load" member from a status body
// and returns it separately, so the lifecycle evidence is decoded strictly
// while the telemetry block is decoded leniently. Duplicate names are
// tolerated only inside the load value (DecodeLoad then drops it): a body
// that is not a single JSON object, repeats a top-level name, or repeats a
// name inside any other member is returned unchanged for the strict decoder
// to refuse.
func SplitLoad(body []byte) (evidence, load []byte) {
	decoder := jsontext.NewDecoder(bytes.NewReader(body), jsontext.AllowDuplicateNames(true))
	if token, err := decoder.ReadToken(); err != nil || token.Kind() != '{' {
		return body, nil
	}
	var out bytes.Buffer
	encoder := jsontext.NewEncoder(&out)
	if encoder.WriteToken(jsontext.BeginObject) != nil {
		return body, nil
	}
	seen := make(map[string]struct{})
	for decoder.PeekKind() == '"' {
		token, err := decoder.ReadToken()
		if err != nil {
			return body, nil
		}
		// A token is only valid until the next read.
		name := token.String()
		if _, repeated := seen[name]; repeated {
			return body, nil
		}
		seen[name] = struct{}{}
		value, err := decoder.ReadValue()
		if err != nil {
			return body, nil
		}
		if name == "load" {
			load = bytes.Clone(value)
			continue
		}
		// The strict encoder refuses duplicate names inside evidence values.
		if encoder.WriteToken(jsontext.String(name)) != nil || encoder.WriteValue(value) != nil {
			return body, nil
		}
	}
	if token, err := decoder.ReadToken(); err != nil || token.Kind() != '}' {
		return body, nil
	}
	if _, err := decoder.ReadToken(); err != io.EOF {
		return body, nil
	}
	if load == nil || encoder.WriteToken(jsontext.EndObject) != nil {
		return body, nil
	}
	return bytes.TrimSpace(out.Bytes()), load
}

func RegionCell(region string) Cell { return Cell{Region: region, Index: 1} }

// Name returns the cell name, e.g. gru-1.
func (c Cell) Name() (string, error) {
	return valid(fmt.Sprintf("%s-%d", strings.ToLower(c.Region), c.Index))
}

// Image returns the name of the cell's qualified ARM64 host image, e.g.
// gru-1-arm64. A new image import reuses the name; the source revision and
// digest belong in its signed receipt.
func (c Cell) Image() (string, error) {
	name, err := c.Name()
	if err != nil {
		return "", err
	}
	return name + "-arm64", nil
}

// Node returns the name of the region's n-th node, e.g. ts-gru-1.
func (c Cell) Node(n int) (string, error) {
	return valid(fmt.Sprintf("ts-%s-%d", strings.ToLower(c.Region), n))
}

// Server returns the name of the cell's n-th server of role, e.g. gru-1-ctl-1.
func (c Cell) Server(role string, n int) (string, error) {
	return valid(fmt.Sprintf("%s-%d-%s-%d", strings.ToLower(c.Region), c.Index, role, n))
}

// PoolServer returns the name of the n-th host of a node pool, e.g.
// gru-1-pool-app-3. A pool name is 2 to 12 lower-case letters and digits,
// starting with a letter.
func (c Cell) PoolServer(pool string, n int) (string, error) {
	return valid(fmt.Sprintf("%s-%d-pool-%s-%d", strings.ToLower(c.Region), c.Index, pool, n))
}

// ControllerSlot returns the server name of a signed controller slot:
// controller-a, -b and -c are the region's nodes 1, 2 and 3 (ts-sfo-1). GRU
// keeps ctl-1, -2 and -3 (gru-1-ctl-1) until its servers are renamed: a
// controller refuses a NATS store of another server name.
func (c Cell) ControllerSlot(slot string) (string, error) {
	if strings.ToUpper(c.Region) == catalog.GRU {
		return c.slot(slot, "controller-", Controller)
	}
	letter, ok := strings.CutPrefix(slot, "controller-")
	if !ok || len(letter) != 1 || letter[0] < 'a' || letter[0] > 'z' {
		return "", fmt.Errorf("%w: controller-slot %q", ErrName, slot)
	}
	return c.Node(int(letter[0]-'a') + 1)
}

// MemberSlot returns the server name of a regional plan's database host
// slot: member-a and -b are db-1 and -2.
func (c Cell) MemberSlot(slot string) (string, error) { return c.slot(slot, "member-", Member) }

func (c Cell) slot(slot, prefix, role string) (string, error) {
	letter, ok := strings.CutPrefix(slot, prefix)
	if !ok || len(letter) != 1 || letter[0] < 'a' || letter[0] > 'z' {
		return "", fmt.Errorf("%w: %sslot %q", ErrName, prefix, slot)
	}
	return c.Server(role, int(letter[0]-'a')+1)
}

// API returns the name of the cell's public API load balancer, e.g.
// gru-1-api, or with a part, of one of its resources, e.g. gru-1-api-subnet.
func (c Cell) API(part string) (string, error) {
	name, err := c.Name()
	if err != nil {
		return "", err
	}
	if part == "" {
		return name + "-api", nil
	}
	if !apiPart.MatchString(part) {
		return "", fmt.Errorf("%w: API part %q", ErrName, part)
	}
	return name + "-api-" + part, nil
}

// Data returns the name of a member's retained data volume, e.g. ts-gru-1-data.
func Data(member string) (string, error) { return valid(member + "-data") }

// Validate accepts only a cell, node, server or data volume name of the
// scheme in a catalog region.
func Validate(name string) error {
	match := nodeScheme.FindStringSubmatch(name)
	if match == nil {
		match = scheme.FindStringSubmatch(name)
	}
	if match == nil || !catalog.IsCell(strings.ToUpper(match[1])) {
		return fmt.Errorf("%w: %q", ErrName, name)
	}
	return nil
}

// IsNode reports whether name is a node of region, ts-<region>-<n> (not its
// data volume).
func IsNode(name, region string) bool {
	match := nodeScheme.FindStringSubmatch(name)
	return match != nil && match[1] == strings.ToLower(region) && !strings.HasSuffix(name, "-data") &&
		catalog.IsCell(strings.ToUpper(region))
}

// NATSServer is a NATS server name: a catalog cell's controller slot gets its
// server name (gru-1-ctl-1); lab cells and instances outside the scheme keep
// <cell>-<instance>.
func NATSServer(cell, instance string) string {
	if name, err := RegionCell(cell).ControllerSlot(instance); err == nil {
		return name
	}
	return cell + "-" + instance
}

func valid(name string) (string, error) {
	if err := Validate(name); err != nil {
		return "", err
	}
	return name, nil
}

func Lookup(cell string) (Entry, bool) {
	for _, entry := range entries {
		if entry.Cell == cell {
			return entry, true
		}
	}
	return Entry{}, false
}

// IsCell reports whether cell is an exact upper-case supported cell code.
func IsCell(cell string) bool {
	_, ok := Lookup(cell)
	return ok
}

// OCIRegion returns the OCI region for an exact cell code, or "" when the cell
// is not supported.
func OCIRegion(cell string) string {
	entry, _ := Lookup(cell)
	return entry.OCIRegion
}

// IsOCIRegion reports whether region is the OCI identifier of a supported cell.
func IsOCIRegion(region string) bool {
	_, ok := CellForOCIRegion(region)
	return ok
}

// CellForOCIRegion maps an exact OCI region identifier back to its cell.
func CellForOCIRegion(region string) (Entry, bool) {
	for _, entry := range entries {
		if entry.OCIRegion == region {
			return entry, true
		}
	}
	return Entry{}, false
}

